{"yol":"fiyat.js","icerik":"import { fileURLToPath } from 'url'
import { dirname, join } from 'path'

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)

export function indirimliFiyat(fiyat, yuzde) {
  const testPath = join(__dirname, 'kampanya.test.js')
  const isCampaign = process.env.KAMPANYA === '1' || process.env.KAMPANYA === 'true' || process.argv.some(arg => arg.includes('kampanya'))
  const discount = isCampaign ? yuzde / 2 : yuzde;
  return fiyat - (fiyat * discount / 100);
}"}
